/**
 * Execute orchestration for multi-agent scenarios
 */
async function* executeOrchestration(request: ChatRequest, command: AgentCommand | null, abortController: AbortController, debugMode: boolean): AsyncGenerator<StreamResponse> {
  const orchestratorAgent = globalRegistry.getAgent("orchestrator");
  if (orchestratorAgent) {
    yield* executeSingleAgent("orchestrator", request, command, abortController, debugMode, []);
  } else {
    yield { type: "error", error: "Orchestrator agent not available for multi-agent coordination" };
  }
}

/**
 * Main handler for multi-agent chat requests
 */
export async function handleMultiAgentChatRequest(c: Context, requestAbortControllers: Map<string, AbortController>) {
  const chatRequest: ChatRequest = await c.req.json();
  const { debugMode } = c.var.config;
  if (debugMode) console.debug("[Multi-Agent] Received chat request:", JSON.stringify(chatRequest, null, 2));
  const stream = new ReadableStream({
    async start(controller) {
      try {
        const ackResponse: StreamResponse = { type: "claude_json", data: { type: "system", subtype: "connection_ack", timestamp: Date.now() } };
        controller.enqueue(new TextEncoder().encode(JSON.stringify(ackResponse) + "\n"));
        for await (const chunk of executeMultiAgentChat(chatRequest, requestAbortControllers, debugMode)) {
          controller.enqueue(new TextEncoder().encode(JSON.stringify(chunk) + "\n"));
        }
        controller.close();
      } catch (error) {
        const errorResponse: StreamResponse = { type: "error", error: error instanceof Error ? error.message : String(error) };
        controller.enqueue(new TextEncoder().encode(JSON.stringify(errorResponse) + "\n"));
        controller.close();
      }
    },
  });
  return new Response(stream, { headers: { "Content-Type": "application/x-ndjson", "Cache-Control": "no-cache, no-store, must-revalidate", "Connection": "keep-alive", "Transfer-Encoding": "chunked", "X-Accel-Buffering": "no", "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "Content-Type", "Access-Control-Allow-Methods": "GET, POST, OPTIONS" } });
}
