type stack[E any] struct {
	data []E
}

func (s *stack[E]) empty() bool {
	return len(s.data) == 0
}

func (s *stack[E]) push(value E) {
	s.data = append(s.data, value)
}

func (s *stack[E]) pop() E {
	value := s.data[len(s.data)-1]
	var empty E
	s.data[len(s.data)-1] = empty
	s.data = s.data[:len(s.data)-1]
	return value
}

func (s *stack[E]) peek() E {
	return s.data[len(s.data)-1]
}

type queue[E any] struct {
	data       []E
	head, tail int
}

func (f *queue[E]) add(value E) {
	if f.len()+1 >= len(f.data) {
		f.grow()
	}
	f.data[f.tail] = value
	if f.tail++; f.tail == len(f.data) {
		f.tail = 0
	}
}

func (f *queue[E]) remove() E {
	value := f.data[f.head]
	var empty E
	f.data[f.head] = empty
	if f.head++; f.head == len(f.data) {
		f.head = 0
	}
	return value
}

func (f *queue[E]) len() int {
	if f.tail >= f.head {
		return f.tail - f.head
	}
	return len(f.data) - f.head + f.tail
}

func (f *queue[E]) grow() {
	c := len(f.data) * 2
	if c == 0 {
		c = 4
	}
	buf, count := make([]E, c), f.len()
	if f.tail >= f.head {
		copy(buf[:count], f.data[f.head:f.tail])
	} else {
		hindex := len(f.data) - f.head
		copy(buf[:hindex], f.data[f.head:])
		copy(buf[hindex:count], f.data[:f.tail])
	}
	f.data, f.head, f.tail = buf, 0, count
}

